static const struct rx3_label_mask sc_label_caption = {
    116u, 16u, sc_label_caption_coverage
};

/* the caption's four variants: dim and white ink on black and blue ground.
   the stock table holds all four; which sits at which id does not matter,
   because each record is measured before it is painted. */
#define SC_CAPTION_FIRST_ID 0x1449u
#define SC_CAPTION_COUNT 4u

/* the select grid's tiles and the beat numbers, for the measurement below. */
#define SC_TILE_FIRST_ID 0x15aau
#define SC_TILE_COUNT 3u
#define SC_BEAT_NUMBER_FIRST_ID 0x1547u
#define SC_BEAT_NUMBER_COUNT 27u

/* every replacement this module keeps alive, so remove() can return them. */
#define SC_LABEL_SLOTS 4u
static struct sc_label_slot {
    void *pixels;
    unsigned long bytes;
} sc_label_slots[SC_LABEL_SLOTS];
static unsigned sc_label_published;

/* Paint one stock caption and take it over. 0 when the record cannot be
   measured, when it is not plain rgb565, or when the image service refuses
   the slot. */
static int sc_label_publish(unsigned image)
{
    struct rx3_native_image stock;
    const uint16_t *read;
    uint16_t *pixels;
    unsigned count;
    unsigned long bytes;
    if (sc_label_published >= SC_LABEL_SLOTS)
        return 0;
    if (!framework->images->stock_image(image, &stock))
        return 0;
    count = (unsigned)stock.width * (unsigned)stock.height;
    if (!count || stock.format != 1u || stock.paletted)
        return 0;
    bytes = (unsigned long)count * 2u;
    pixels = mmap(0, (size_t)bytes, PROT_READ | PROT_WRITE,
                  MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pixels == MAP_FAILED)
        return 0;
    read = (const uint16_t *)stock.pixels;
    rx3_label_paint(pixels, stock.width, stock.height, read[0],
                    rx3_label_ink(read, count, read[0]), &sc_label_caption);
    if (!framework->images->replace_native(&sc_owner, image, pixels, pixels,
                                           stock.width, stock.height)) {
        munmap(pixels, (size_t)bytes);
        return 0;
    }
    sc_label_slots[sc_label_published].pixels = pixels;
    sc_label_slots[sc_label_published].bytes = bytes;
    sc_label_published++;
    return 1;
}

/* What the rest of the relabel needs, written to the module log: the select
   grid's tile geometry and the beat number's. The tile ids sit next to the
   caption in the stock table, so once these lines are in hand the tiles are
   the same paint at a re-rasterised mask. */
static void sc_label_measure(void)
{
    struct rx3_native_image stock;
    unsigned index;
    for (index = 0; index < SC_TILE_COUNT; index++) {
        unsigned image = SC_TILE_FIRST_ID + index;
        if (!framework->images->stock_image(image, &stock))
            continue;
        framework->log_number("sidechain: select tile id = ", image);
        framework->log_number("sidechain: select tile width = ", stock.width);
        framework->log_number("sidechain: select tile height = ", stock.height);
        framework->log_number("sidechain: select tile format = ", stock.format);
    }
    if (!framework->images->stock_image(SC_BEAT_NUMBER_FIRST_ID, &stock))
        return;
    framework->log_number("sidechain: beat number width = ", stock.width);
    framework->log_number("sidechain: beat number height = ", stock.height);
    framework->log_number("sidechain: beat number ids = ", SC_BEAT_NUMBER_COUNT);
}

/* The caption is cosmetic: a refusal here does not stop the module. */
static void sc_labels_install(void)
{
    unsigned index;
    unsigned made = 0;
    if (!framework->images || !framework->images->stock_image ||
        !framework->images->replace_native) {
        framework->log_line("sidechain: the caption needs the image service");
        return;
    }
    for (index = 0; index < SC_CAPTION_COUNT; index++)
        made += (unsigned)sc_label_publish(SC_CAPTION_FIRST_ID + index);
    framework->log_number("sidechain: captions relabelled = ", made);
    sc_label_measure();
}

/* The service refuses once the tables have published, because from then on
   the live table points at these pixels: freeing them would leave the play
   screen reading released memory. So they are freed only when the service
   let them go. */
static void sc_labels_release(void)
{
    unsigned index;
    if (!framework->images)
        return;
    if (!framework->images->release_native(&sc_owner))
        return;
    for (index = 0; index < SC_LABEL_SLOTS; index++) {
        if (!sc_label_slots[index].pixels)
            continue;
        munmap(sc_label_slots[index].pixels,
               (size_t)sc_label_slots[index].bytes);
    }
    memset(sc_label_slots, 0, sizeof(sc_label_slots));
    sc_label_published = 0;
}

#endif /* RX3_SIDECHAIN_LABELS_H */
